fn calculate_discount(price: i32, rate: i32) -> i32 {
    let mut final_price: i32 = price;
    if rate > 0 {
        let discount: i32 = (price * rate) / 100;
        final_price = price - discount;
    }
    return final_price;
}

fn main() -> i32 {
    printf("=== بروتوكول برهان الحتمية الشامل ===\n");
    let mut all_passed: i32 = 1;
    let res_100_20: i32 = calculate_discount(100, 20);
    if res_100_20 != 80 {
        printf("❌ فشل عند (100, 20): الناتج %d، المتوقع 80\n", res_100_20);
        all_passed = 0;
    }
    let res_200_0: i32 = calculate_discount(200, 0);
    if res_200_0 != 200 {
        printf("❌ فشل عند (200, 0): الناتج %d، المتوقع 200\n", res_200_0);
        all_passed = 0;
    }
    let res_50_10: i32 = calculate_discount(50, 10);
    if res_50_10 != 45 {
        printf("❌ فشل عند (50, 10): الناتج %d، المتوقع 45\n", res_50_10);
        all_passed = 0;
    }
    let res_100_50: i32 = calculate_discount(100, 50);
    if res_100_50 != 50 {
        printf("❌ فشل عند (100, 50): الناتج %d، المتوقع 50\n", res_100_50);
        all_passed = 0;
    }
    if all_passed == 1 {
        printf("✅ [PROOF PASSED]: جميع حالات الاختبار مطابقة حتمياً.\n");
        return 0;
    } else {
        printf("❌ [PROOF FAILED]: انهيار في الحتمية.\n");
        return 1;
    }
}

